func TestFounderRuntimeQuarantinedLateResultRepairsPinnedCandidate(t *testing.T) {
	fixture, caller, objects, fake := newFounderRuntimeFixture(t)
	const slot = "controller-a"
	if err := caller.runPeer(t.Context(), slot); err != nil {
