func (reader *CurrentFounderAuthorityReader) ReadCurrent(ctx context.Context, now time.Time) (CurrentFounderAuthority, error) {
	if reader != nil && reader.derived != nil {
		return reader.readDerivedCurrent(ctx, now, true)
	}
	return reader.readCurrent(ctx, now, true)
}

// The peer paths share current signature and exact-key verification with the
// seed reader. Initial peer admission establishes its floor after this read.
func (reader *CurrentFounderAuthorityReader) readCurrentPeerInitial(ctx context.Context, now time.Time) (currentFounderPeerSelection, error) {
	if reader != nil && reader.derived != nil {
		return reader.readDerivedCompletedPeer(ctx, now, false)
	}
	return reader.readCurrentCompletedPeer(ctx, now, false)
}

func (reader *CurrentFounderAuthorityReader) readCurrent(ctx context.Context, now time.Time,
	useFloor bool,
) (CurrentFounderAuthority, error) {
	if reader == nil || reader.objects == nil || reader.floor == nil ||
		now.IsZero() || now.Location() != time.UTC {
		return CurrentFounderAuthority{}, ErrFounderSelection
	}
	started := time.Now()
	selectorKey := FounderSelectionObjectName(reader.domain, reader.baked.Identity.DeploymentID,
		string(reader.baked.Identity.Cell), reader.baked.Identity.Environment)
	firstWire, firstETag, err := reader.getExact(ctx, reader.domain.HeadBucket, selectorKey, founderSelectionMaxBytes)
	if err != nil {
		return CurrentFounderAuthority{}, err
	}
	selection, selectionDigest, selectionExpiresAt, err := reader.verifySelection(firstWire, now)
	if err != nil {
		return CurrentFounderAuthority{}, err
	}
	if selection.SchemaVersion != 1 {
		return CurrentFounderAuthority{}, ErrFounderSelection
	}
	if useFloor {
		if err := reader.floor.Check(selection.Generation, selectionDigest); err != nil {
			return CurrentFounderAuthority{}, err
		}
	}
	getImmutable := func(digest string) ([]byte, error) {
		name := FounderImmutableObjectName(reader.domain, selection.DeploymentID, selection.Cell, selection.Environment, digest)
		wire, _, err := reader.getExact(ctx, reader.domain.LedgerBucket, name, founderObjectMaxBytes)
		if err != nil {
			return nil, err
		}
		if digestWire(wire) != digest {
			return nil, fmt.Errorf("%w: immutable object digest differs from selector", ErrFounderSelection)
		}
		return wire, nil
	}
	planWire, err := getImmutable(selection.PlanSHA256)
	if err != nil {
		return CurrentFounderAuthority{}, err
	}
	anchorWire, err := getImmutable(selection.AnchorSHA256)
	if err != nil {
		return CurrentFounderAuthority{}, err
	}
	manifests := make(map[string][]byte, len(selection.Manifests))
	for _, pin := range selection.Manifests {
		wire, err := getImmutable(pin.SHA256)
		if err != nil {
			return CurrentFounderAuthority{}, err
		}
		manifests[pin.Slot] = wire
	}
	if err := reader.confirmSelector(ctx, selectorKey, firstWire, firstETag); err != nil {
		return CurrentFounderAuthority{}, err
	}
	anchorEnvelope, err := trust.DecodeEnvelope(anchorWire)
	if err != nil {
		return CurrentFounderAuthority{}, fmt.Errorf("%w: decode selected anchor: %v", ErrFounderSelection, err)
	}
	currentNow := now.Add(time.Since(started))
	anchor, err := bootstrap.VerifyBootstrapAnchor(anchorEnvelope, reader.baked.Roots,
		reader.baked.Identity.AnchorExpectation(), currentNow, bootstrap.BootstrapAnchorTrustPolicy())
	if err != nil || anchor.Digest() != selection.AnchorSHA256 || anchor.StorageDomain() != reader.domain ||
		anchor.Anchor().ClusterID != reader.acceptedClusterID {
		return CurrentFounderAuthority{}, fmt.Errorf("%w: selected anchor or discovery domain differs: %v", ErrFounderSelection, err)
	}
	plan, err := bootstrap.VerifyFounderPlan(planWire, reader.baked.Roots, anchorWire, manifests, currentNow,
		trust.Policy{MaxLifetime: 24 * time.Hour, ClockSkew: bootstrap.ManifestClockSkew})
	if err != nil {
		return CurrentFounderAuthority{}, fmt.Errorf("%w: selected founder proof: %w", ErrFounderSelection, err)
	}
	if plan.Digest() != selection.PlanSHA256 || plan.Plan().SeedSlot != reader.accepted.Slot ||
		plan.Plan().SeedManifestSHA256 != reader.accepted.ManifestSHA256 {
		return CurrentFounderAuthority{}, fmt.Errorf("%w: selected plan does not match accepted seed", ErrFounderSelection)
	}
	if useFloor {
		if err := reader.floor.Observe(selection.Generation, selectionDigest); err != nil {
			return CurrentFounderAuthority{}, err
		}
	}
	if err := reader.confirmSelector(ctx, selectorKey, firstWire, firstETag); err != nil {
		return CurrentFounderAuthority{}, err
	}
	if !now.Add(time.Since(started)).Before(selectionExpiresAt) {
		return CurrentFounderAuthority{}, fmt.Errorf("%w: selector expired during read", ErrFounderSelection)
	}
	return CurrentFounderAuthority{SelectionGeneration: selection.Generation, SelectionSHA256: selectionDigest,
		SelectionExpiresAt: selectionExpiresAt,
		Plan:               plan, Anchor: anchor, PlanWire: bytes.Clone(planWire), AnchorWire: bytes.Clone(anchorWire),
		ManifestWires: manifests}, nil
}

func (store FounderSignerStore) LoadContext(ctx context.Context, current CurrentFounderAuthority, accepted AcceptedInstall, roots trust.Keyring, now time.Time) (FounderSigningKeys, error) {
	if accepted.validate() != nil || current.Plan == nil || !current.Plan.IsVerified() || !current.Anchor.IsVerified() ||
		len(roots) == 0 || now.IsZero() || now.Location() != time.UTC ||
		!now.Before(current.SelectionExpiresAt) {
		return FounderSigningKeys{}, ErrFounderSigner
	}
	plan := current.Plan.Plan()
	anchor := current.Anchor.Anchor()
	if plan.SeedSlot != accepted.Slot || plan.SeedManifestSHA256 != accepted.ManifestSHA256 ||
		plan.DeploymentID != accepted.DeploymentID || string(plan.Cell) != accepted.Cell ||
		anchor.ClusterID == "" || plan.AnchorSHA256 != current.Anchor.Digest() {
		return FounderSigningKeys{}, ErrFounderSigner
	}
	seed, err := verifiedFounderManifestContext(ctx, current, accepted.Slot, roots, now)
	if err != nil || seed.Digest() != accepted.ManifestSHA256 {
		return FounderSigningKeys{}, fmt.Errorf("%w: selected accepted seed manifest: %v", ErrFounderSigner, err)
	}
	manifest := seed.Manifest()
	peerReference, err := exactSeedSignerReference(manifest, bootstrap.SecretSeedFounder)
	if err != nil {
		return FounderSigningKeys{}, err
	}
	ledgerReference, err := exactSeedSignerReference(manifest, bootstrap.SecretSeedLedgerSigner)
	if err != nil {
		return FounderSigningKeys{}, err
	}
	if current.Derived != nil {
		return store.loadDerivedKeys(ctx, *current.Derived, accepted, peerReference, ledgerReference, now)
	}
	ledgerGrant, err := current.Anchor.LedgerDelegation()
	if err != nil {
		return FounderSigningKeys{}, fmt.Errorf("%w: selected ledger delegation: %v", ErrFounderSigner, err)
	}
	var peerKeyID string
	for _, row := range plan.Peers {
		peerManifest, err := verifiedFounderManifest(current, row.Slot, roots, now)
		if err != nil || peerManifest.Digest() != row.ManifestSHA256 {
			return FounderSigningKeys{}, fmt.Errorf("%w: selected peer manifest %q: %v", ErrFounderSigner, row.Slot, err)
		}
		peerDelegation := peerManifest.Manifest().PeerReceiptDelegation
		if peerDelegation == nil {
			return FounderSigningKeys{}, ErrFounderSigner
		}
		verified, err := trust.VerifyDelegationCurrent(*peerDelegation, roots, now, bootstrap.ManifestTrustPolicy())
		if err != nil || peerKeyID != "" && peerKeyID != verified.SubjectKeyID() {
			return FounderSigningKeys{}, fmt.Errorf("%w: peer receipt delegations differ or expired: %v", ErrFounderSigner, err)
		}
		peerKeyID = verified.SubjectKeyID()
	}
	if peerKeyID == "" || peerKeyID == ledgerGrant.SubjectKeyID() {
		return FounderSigningKeys{}, fmt.Errorf("%w: receipt and ledger signing roles require distinct delegated keys", ErrFounderSigner)
	}
	fd, err := openMaterialDirectory(store.directory, store.uid, store.gid, 0o700, store.allowUnsafeAncestors)
	if err != nil {
		return FounderSigningKeys{}, fmt.Errorf("%w: open installed seed material: %v", ErrFounderSigner, err)
	}
	defer unix.Close(fd)
	peerKey, err := store.readKey(fd, peerReference, accepted.MaterialSHA256, peerKeyID)
	if err != nil {
		return FounderSigningKeys{}, err
	}
	ledgerKey, err := store.readKey(fd, ledgerReference, accepted.MaterialSHA256, ledgerGrant.SubjectKeyID())
	if err != nil {
		clear(peerKey)
		return FounderSigningKeys{}, err
	}
	return FounderSigningKeys{peer: peerKey, ledger: ledgerKey}, nil
}

func exactSeedSignerReference(manifest bootstrap.Manifest, purpose bootstrap.SecretPurpose) (bootstrap.SecretReference, error) {
	var selected bootstrap.SecretReference
	count := 0
	for _, reference := range manifest.Secrets {
		if reference.Purpose == purpose {
			if reference.Slot != manifest.SeedSlot {
				return bootstrap.SecretReference{}, ErrFounderSigner
			}
			selected = reference
			count++
		}
	}
	if count != 1 {
		return bootstrap.SecretReference{}, ErrFounderSigner
	}
	return selected, nil
}

func (store FounderSignerStore) readKey(fd int, reference bootstrap.SecretReference,
	installed map[string]string, delegatedKeyID string,
) (ed25519.PrivateKey, error) {
	if installed[reference.TargetFile] != reference.SHA256 {
		return nil, fmt.Errorf("%w: installed material digest differs from seed manifest", ErrFounderSigner)
	}
	wire, err := readMaterial(fd, reference.TargetFile, store.uid, store.gid, reference.SHA256, reference.MaxBytes)
	if err != nil {
		return nil, fmt.Errorf("%w: read exact installed signer: %v", ErrFounderSigner, err)
	}
	defer clear(wire)
	if len(wire) != ed25519.PrivateKeySize ||
		!bytes.Equal(ed25519.NewKeyFromSeed(wire[:ed25519.SeedSize]), wire) {
		return nil, ErrFounderSigner
	}
	key := ed25519.PrivateKey(bytes.Clone(wire))
	keyID, err := trust.KeyID(key.Public().(ed25519.PublicKey))
	if err != nil || keyID != delegatedKeyID {
		clear(key)
		return nil, fmt.Errorf("%w: installed signer key differs from current root delegation", ErrFounderSigner)
	}
	return key, nil
}

func readMaterial(dir int, name string, uid, gid uint32, want string, maximum int64) ([]byte, error) {
	if !markerNameRE.MatchString(name) || !markerDigestRE.MatchString(want) || maximum <= 0 || maximum > bootstrap.MaxSecretBytes {
		return nil, ErrMaterial
	}
	fd, err := unix.Openat(dir, name, unix.O_RDONLY|unix.O_CLOEXEC|unix.O_NOFOLLOW|unix.O_NONBLOCK, 0)
	if err != nil {
		return nil, err
	}
	file := os.NewFile(uintptr(fd), name)
	defer file.Close()
	var stat unix.Stat_t
	if err := unix.Fstat(fd, &stat); err != nil || stat.Mode&unix.S_IFMT != unix.S_IFREG ||
		stat.Uid != uid || stat.Gid != gid || stat.Mode&0o777 != 0o600 || stat.Nlink != 1 ||
		stat.Size <= 0 || stat.Size > maximum {
		return nil, ErrMaterial
	}
	content, err := io.ReadAll(io.LimitReader(file, maximum+1))
	if err != nil || len(content) == 0 || int64(len(content)) > maximum || digest(content) != want {
		clear(content)
		return nil, ErrMaterial
	}
	return content, nil
}

func openMaterialDirectory(path string, uid, gid uint32, mode uint32, allowUnsafeAncestors bool) (int, error) {
	if !filepath.IsAbs(path) || filepath.Clean(path) != path {
		return -1, ErrMaterial
	}
	fd, err := unix.Open("/", unix.O_RDONLY|unix.O_DIRECTORY|unix.O_CLOEXEC, 0)
	if err != nil {
		return -1, err
	}
	components := strings.Split(strings.TrimPrefix(path, "/"), "/")
	for index, component := range components {
		if component == "" || component == "." || component == ".." {
			unix.Close(fd)
			return -1, ErrMaterial
		}
		next, err := unix.Openat(fd, component, unix.O_RDONLY|unix.O_DIRECTORY|unix.O_CLOEXEC|unix.O_NOFOLLOW, 0)
		unix.Close(fd)
		if err != nil {
			return -1, err
		}
		fd = next
		var stat unix.Stat_t
		if err := unix.Fstat(fd, &stat); err != nil ||
			index < len(components)-1 && !allowUnsafeAncestors && (stat.Uid != 0 || stat.Mode&0o022 != 0) {
			unix.Close(fd)
			return -1, ErrMaterial
		}
	}
	var stat unix.Stat_t
	if err := unix.Fstat(fd, &stat); err != nil || stat.Uid != uid || stat.Gid != gid || stat.Mode&0o777 != mode {
		unix.Close(fd)
		return -1, ErrMaterial
	}
	return fd, nil
}

