func (adapter *FounderOCI) beforeEffect(ctx context.Context, attempt FounderOCIAttempt, refresh FounderPeerRefresh) (context.Context, context.CancelFunc, error) {
	if err := ctx.Err(); err != nil {
		return nil, nil, err
	}
	if adapter == nil || adapter.compute == nil || adapter.network == nil || adapter.volume == nil ||
		!attempt.valid || refresh == nil || attempt.request.Cell != adapter.region {
		return nil, nil, ErrFounderOCI
	}
	refreshStarted := time.Now()
	peer, now, selectionExpiresAt, err := refresh(ctx)
	if err != nil {
		return nil, nil, fmt.Errorf("refresh founder authority: %w", err)
	}
	var current bootstrap.FounderPeerLaunchRequest
	if attempt.observationOnly {
		observation, observationErr := peer.ObservationRequest(now)
		if observationErr != nil || observation.InstanceOCID != attempt.candidateID {
			return nil, nil, ErrFounderOCI
		}
		current = observation.Launch
	} else {
		current, err = peer.LaunchRequest(now)
		if err != nil {
			return nil, nil, err
		}
	}
	if !sameFounderAttempt(attempt, current, peer.EffectDeadline(), now) {
		return nil, nil, ErrFounderOCI
	}
	if selectionExpiresAt.IsZero() || selectionExpiresAt.Location() != time.UTC {
		return nil, nil, ErrFounderOCI
	}
	remaining := min(peer.EffectDeadline().Sub(now), attempt.deadline.Sub(now), selectionExpiresAt.Sub(now)) -
		time.Since(refreshStarted)
	if remaining <= 0 {
		return nil, nil, bootstrap.ErrFounderPlanExpired
	}
	effectCtx, cancel := context.WithTimeout(ctx, remaining)
	return effectCtx, cancel, nil
}

func sameFounderAttempt(attempt FounderOCIAttempt, current bootstrap.FounderPeerLaunchRequest, deadline, now time.Time) bool {
	previous := attempt.request
	for _, request := range []bootstrap.FounderPeerLaunchRequest{previous, current} {
		if request.StartupAuthority != nil && request.StartupAuthority.Digest() != request.ManifestSHA256 {
			return false
		}
	}
	previous.StartupAuthority, current.StartupAuthority = nil, nil
	return attempt.valid && !attempt.deadline.IsZero() && !deadline.After(attempt.deadline) &&
		now.Location() == time.UTC && now.Before(attempt.deadline) && reflect.DeepEqual(current, previous)
}

func noFounderSDKRetry() common.RequestMetadata {
	policy := common.NoRetryPolicy()
	return common.RequestMetadata{RetryPolicy: &policy}
}

func (adapter *FounderOCI) checkImage(ctx context.Context, attempt FounderOCIAttempt, refresh FounderPeerRefresh) error {
	effectCtx, cancel, err := adapter.beforeEffect(ctx, attempt, refresh)
	if err != nil {
		return err
	}
	defer cancel()
	row := attempt.request.Row
	response, err := adapter.compute.GetImage(effectCtx, core.GetImageRequest{
		ImageId: new(row.ImageOCID), RequestMetadata: noFounderSDKRetry(),
	})
	if err != nil {
		return fmt.Errorf("GetImage exact founder image: %w", err)
	}
	if !founderImageMatches(response.Image, row) {
		return ErrFounderOCI
	}
	return nil
}

// Launch performs one OCI LaunchInstance request. A lost response is ambiguous;
// retry only by calling Launch again with the same attempt and a fresh reader.
// No tag or display-name search can recover or adopt an instance here.
func (adapter *FounderOCI) Launch(ctx context.Context, attempt FounderOCIAttempt, refresh FounderPeerRefresh) (string, error) {
	if attempt.observationOnly {
		return "", ErrFounderOCI
	}
	if err := adapter.checkImage(ctx, attempt, refresh); err != nil {
		return "", err
	}
	effectCtx, cancel, err := adapter.beforeEffect(ctx, attempt, refresh)
	if err != nil {
		return "", err
	}
	defer cancel()
	request, err := founderLaunchSDKRequest(attempt.request, adapter.material)
	if err != nil {
		return "", err
	}
	if err := effectCtx.Err(); err != nil {
		return "", err
	}
	response, err := adapter.compute.LaunchInstance(effectCtx, request)
	if err != nil {
		return "", fmt.Errorf("LaunchInstance founder peer: %w", err)
	}
	id := value(response.Id)
	if !founderLaunchCandidateMatches(response.Instance, attempt.request.Row) {
		return "", ErrFounderOCI
	}
	return id, nil
}

func (adapter *FounderOCI) Observe(ctx context.Context, attempt FounderOCIAttempt, refresh FounderPeerRefresh, instanceID string) (FounderOCIObservation, error) {
	started := time.Now()
	if !instanceIDRE.MatchString(instanceID) || attempt.observationOnly && instanceID != attempt.candidateID {
		return FounderOCIObservation{}, ErrFounderOCI
	}
	row := attempt.request.Row
	effectCtx, cancel, err := adapter.beforeEffect(ctx, attempt, refresh)
	if err != nil {
		return FounderOCIObservation{}, err
	}
	instanceResponse, err := adapter.compute.GetInstance(effectCtx, core.GetInstanceRequest{
		InstanceId: new(instanceID), RequestMetadata: noFounderSDKRetry(),
	})
	cancel()
	if err != nil {
		return FounderOCIObservation{}, fmt.Errorf("GetInstance exact founder candidate: %w", err)
	}
	instance := instanceResponse.Instance
	descriptor, err := protocol.EncodeJSON(Descriptor{SchemaVersion: 1, Slot: attempt.request.Slot})
	if err != nil {
		return FounderOCIObservation{}, err
	}
	if !founderInstanceMatches(instance, instanceID, row, string(descriptor)) || value(instanceResponse.Etag) == "" {
		return FounderOCIObservation{}, ErrFounderOCI
	}
	if err := adapter.checkImage(ctx, attempt, refresh); err != nil {
		return FounderOCIObservation{}, err
	}
	vnicID, err := adapter.observeFounderVNIC(ctx, attempt, refresh, instanceID)
	if err != nil {
		return FounderOCIObservation{}, err
	}
	bootID, volume, observedAt, err := adapter.observeFounderBootVolume(ctx, attempt, refresh, instanceID)
	if err != nil {
		return FounderOCIObservation{}, err
	}
	if !founderObservationImageProven(instance, volume, row) {
		return FounderOCIObservation{}, ErrFounderOCI
	}
	finished := time.Now()
	if finished.Sub(started) > bootstrap.ManagedPeerObservationMaxAge || observedAt.IsZero() || observedAt.Location() != time.UTC {
		return FounderOCIObservation{}, ErrFounderOCI
	}
	return FounderOCIObservation{
		InstanceOCID: instanceID, InstanceETag: value(instanceResponse.Etag), PrimaryVNICID: vnicID,
		BootVolumeID: bootID, CompartmentID: row.CompartmentOCID, ImageID: row.ImageOCID,
		PrivateIP: row.PrivateIP, Shape: row.Shape, WholeOCPUs: row.WholeOCPUs,
		MemoryInGB: row.MemoryInGB, BootVolumeGB: row.BootVolumeGB, BootVPUsPerGB: 10,
		ObservedAt: observedAt, observedMono: finished,
	}, nil
}

func (adapter *FounderOCI) observeFounderBootVolume(ctx context.Context, attempt FounderOCIAttempt, refresh FounderPeerRefresh, instanceID string) (string, core.BootVolume, time.Time, error) {
	row := attempt.request.Row
	effectCtx, cancel, err := adapter.beforeEffect(ctx, attempt, refresh)
	if err != nil {
		return "", core.BootVolume{}, time.Time{}, err
	}
	attachments, err := adapter.compute.ListBootVolumeAttachments(effectCtx, core.ListBootVolumeAttachmentsRequest{
		AvailabilityDomain: new(row.AvailabilityDomain), CompartmentId: new(row.CompartmentOCID),
		InstanceId: new(instanceID), RequestMetadata: noFounderSDKRetry(),
	})
	cancel()
	if err != nil {
		return "", core.BootVolume{}, time.Time{}, fmt.Errorf("ListBootVolumeAttachments founder candidate: %w", err)
	}
	if value(attachments.OpcNextPage) != "" || len(attachments.Items) != 1 {
		return "", core.BootVolume{}, time.Time{}, ErrFounderOCI
	}
	attachment := attachments.Items[0]
	bootID := value(attachment.BootVolumeId)
	if value(attachment.InstanceId) != instanceID || value(attachment.CompartmentId) != row.CompartmentOCID ||
		value(attachment.AvailabilityDomain) != row.AvailabilityDomain ||
		attachment.LifecycleState != core.BootVolumeAttachmentLifecycleStateAttached ||
		!strings.HasPrefix(bootID, "ocid1.bootvolume.") {
		return "", core.BootVolume{}, time.Time{}, ErrFounderOCI
	}
	effectCtx, cancel, err = adapter.beforeEffect(ctx, attempt, refresh)
	if err != nil {
		return "", core.BootVolume{}, time.Time{}, err
	}
	response, err := adapter.volume.GetBootVolume(effectCtx, core.GetBootVolumeRequest{
		BootVolumeId: new(bootID), RequestMetadata: noFounderSDKRetry(),
	})
	cancel()
	if err != nil {
		return "", core.BootVolume{}, time.Time{}, fmt.Errorf("GetBootVolume exact founder boot volume: %w", err)
	}
	volume := response.BootVolume
	if !founderBootVolumeMatches(volume, bootID, row) {
		return "", core.BootVolume{}, time.Time{}, ErrFounderOCI
	}
	if response.RawResponse == nil {
		return "", core.BootVolume{}, time.Time{}, ErrFounderOCI
	}
	observedAt, err := http.ParseTime(response.RawResponse.Header.Get("Date"))
	if err != nil || observedAt.IsZero() {
		return "", core.BootVolume{}, time.Time{}, ErrFounderOCI
	}
	return bootID, volume, observedAt.UTC(), nil
}

type founderStoredObject struct {
	wire     []byte
	etag     string
	modified time.Time
}

type founderLedgerObjects struct {
	objects      map[string]founderStoredObject
	now          time.Time
	rejectSuffix string
	rejectPart   string
	afterGet     func(string)
	writes       int
}

func (store *founderLedgerObjects) PutObject(_ context.Context, request objectstorage.PutObjectRequest) (objectstorage.PutObjectResponse, error) {
	if request.NamespaceName == nil || request.BucketName == nil || request.ObjectName == nil ||
		request.OpcSseKmsKeyId == nil || request.PutObjectBody == nil {
		return objectstorage.PutObjectResponse{}, errors.New("incomplete founder ledger write")
	}
	wire, err := io.ReadAll(request.PutObjectBody)
	if err != nil {
		return objectstorage.PutObjectResponse{}, err
	}
	_ = request.PutObjectBody.Close()
	if request.ContentLength == nil || *request.ContentLength != int64(len(wire)) ||
		request.OpcContentSha256 == nil || *request.OpcContentSha256 != base64Digest(wire) {
		return objectstorage.PutObjectResponse{}, errors.New("founder ledger write changed content")
	}
	if store.rejectSuffix != "" && strings.HasSuffix(*request.ObjectName, store.rejectSuffix) ||
		store.rejectPart != "" && strings.Contains(*request.ObjectName, store.rejectPart) {
		return objectstorage.PutObjectResponse{}, errors.New("injected founder ledger write failure")
	}
	key := *request.BucketName + "/" + *request.ObjectName
	previous, exists := store.objects[key]
	if request.IfNoneMatch != nil && *request.IfNoneMatch == "*" && exists ||
		request.IfMatch != nil && (!exists || previous.etag != *request.IfMatch) {
		return objectstorage.PutObjectResponse{}, founderStorageError(http.StatusPreconditionFailed)
	}
	if request.IfNoneMatch == nil && request.IfMatch == nil {
		return objectstorage.PutObjectResponse{}, errors.New("unconditional founder ledger write")
	}
	hash := sha256.Sum256(wire)
	etag := `"` + hex.EncodeToString(hash[:8]) + `"`
	store.objects[key] = founderStoredObject{wire: bytes.Clone(wire), etag: etag, modified: store.now}
	store.writes++
	return objectstorage.PutObjectResponse{ETag: new(etag)}, nil
}

func (store *founderLedgerObjects) GetObject(_ context.Context, request objectstorage.GetObjectRequest) (objectstorage.GetObjectResponse, error) {
	if request.NamespaceName == nil || request.BucketName == nil || request.ObjectName == nil {
		return objectstorage.GetObjectResponse{}, errors.New("incomplete founder ledger read")
	}
	object, ok := store.objects[*request.BucketName+"/"+*request.ObjectName]
	if !ok {
		return objectstorage.GetObjectResponse{}, founderStorageError(http.StatusNotFound)
	}
	headers := make(http.Header)
	headers.Set("Date", store.now.Format(http.TimeFormat))
	length := int64(len(object.wire))
	modified := common.SDKTime{Time: object.modified}
	if store.afterGet != nil {
		store.afterGet(*request.ObjectName)
	}
	return objectstorage.GetObjectResponse{RawResponse: &http.Response{Header: headers},
		Content: io.NopCloser(bytes.NewReader(object.wire)), ContentLength: &length,
		ETag: new(object.etag), LastModified: &modified}, nil
}

type founderStorageError int

func (err founderStorageError) Error() string           { return http.StatusText(int(err)) }
func (err founderStorageError) GetHTTPStatusCode() int  { return int(err) }
func (err founderStorageError) GetMessage() string      { return err.Error() }
func (err founderStorageError) GetCode() string         { return "FounderTest" }
func (err founderStorageError) GetOpcRequestID() string { return "founder-test" }

func (ledger *Ledger) readObject(ctx context.Context, bucket, objectName string) (StoredRecord, error) {
	return ledger.readObjectLimit(ctx, bucket, objectName, ledger.maxRecord)
}

func (ledger *Ledger) readObjectLimit(ctx context.Context, bucket, objectName string, maximum int) (StoredRecord, error) {
	if ledger.config.DerivedStartup != nil {
		authority := *ledger.config.DerivedStartup
		if ledger.now().Before(authority.ExpiresAt()) {
			if err := authority.VerifyCurrent(ctx, ledger.now()); err != nil {
				return StoredRecord{}, err
			}
		} else if _, err := authority.historical(ctx, authority.Wire()); err != nil {
			return StoredRecord{}, err
		}
	}
	response, err := ledger.client.GetObject(ociclient.RequestContext(ctx), objectstorage.GetObjectRequest{
		NamespaceName: new(ledger.config.Namespace),
		BucketName:    new(bucket),
		ObjectName:    new(objectName),
	})
	if err != nil {
		if serviceErr, ok := errors.AsType[objectStorageServiceError](err); ok && serviceErr.GetHTTPStatusCode() == http.StatusNotFound {
			return StoredRecord{}, ErrRecordMissing
		}
		return StoredRecord{}, fmt.Errorf("read exact bootstrap object: %w", err)
	}
	if response.Content == nil {
		return StoredRecord{}, errors.New("bootstrap object response has no body")
	}
	if response.ContentLength == nil || *response.ContentLength < 1 || *response.ContentLength > int64(maximum) {
		response.Content.Close()
		return StoredRecord{}, errors.New("bootstrap object has missing or invalid content length")
	}
	body, err := io.ReadAll(io.LimitReader(response.Content, int64(maximum)+1))
	closeErr := response.Content.Close()
	if err := errors.Join(err, closeErr); err != nil {
		return StoredRecord{}, fmt.Errorf("read bootstrap object body: %w", err)
	}
	if len(body) != int(*response.ContentLength) || len(body) > maximum {
		return StoredRecord{}, errors.New("bootstrap object body length does not match its metadata")
	}
	if response.ETag == nil || strings.TrimSpace(*response.ETag) == "" || response.LastModified == nil {
		return StoredRecord{}, errors.New("bootstrap object is missing ETag or Last-Modified metadata")
	}
	if response.RawResponse == nil {
		return StoredRecord{}, errors.New("bootstrap object response is missing server headers")
	}
	serverDate, err := http.ParseTime(response.RawResponse.Header.Get("Date"))
	if err != nil {
		return StoredRecord{}, errors.New("bootstrap object response has a missing or invalid server Date")
	}
	lastModified := response.LastModified.Time.UTC()
	serverDate = serverDate.UTC()
	if lastModified.IsZero() || serverDate.Before(lastModified) {
		return StoredRecord{}, errors.New("bootstrap object server timestamps are inconsistent")
	}
	digest := sha256.Sum256(body)
	return StoredRecord{
		Bytes: body, SHA256: hex.EncodeToString(digest[:]), ETag: *response.ETag,
		LastModified: lastModified, ServerDate: serverDate,
	}, nil
}

func (ledger *Ledger) ReserveSlot(ctx context.Context, scope BootstrapScope, intentBytes, initialHeadBytes []byte) (SlotState, error) {
	if err := validateLedgerScope(scope); err != nil {
		return SlotState{}, err
	}
	if err := ledger.validateAnchorScope(scope); err != nil {
		return SlotState{}, err
	}
	intent, intentEnvelope, intentErr := ledger.decodeIntent(scope, intentBytes, true)
	if intentErr != nil {
		return SlotState{}, intentErr
	}
	if intent.Attempt != 1 || intent.Generation != 1 {
		return SlotState{}, fmt.Errorf("%w: an initial reservation must begin at attempt and generation one", ErrInvalidRecord)
	}
	head, headErr := ledger.decodeHead(scope, initialHeadBytes, true)
	headAuthorizedNow := headErr == nil
	if headErr != nil {
		return SlotState{}, headErr
	}
	if head.Attempt != intent.Attempt || head.Generation != intent.Generation || head.IntentDigest != objectDigest(intentBytes) ||
		head.ResultDigest != "" || head.CandidateDigest != "" || head.PreviousAttempt != 0 || head.RetirementDigest != "" {
		return SlotState{}, ErrSlotNotReserved
	}
	intentRecord, err := ledger.createOrRead(ctx, scope, intent.Attempt, ledgerIntent, intentBytes)
	if err != nil {
		return SlotState{}, err
	}
	clockErr := validIntentClock(intent, intentRecord, ledger.config.TrustPolicy.ClockSkew)
	if clockErr != nil {
		return SlotState{}, clockErr
	}
	if err := validateStoredInterval(intentRecord, intentEnvelope); err != nil {
		return SlotState{}, err
	}
	if err := ledger.validateStoredBeforeAnchorExpiry(intentRecord); err != nil {
		return SlotState{}, err
	}
	// Intent creation and HEAD admission are separate Object Storage calls. The
	// intent may expire while the HEAD write is in flight, so verify current
	// authority again immediately before admitting the initial HEAD.
	currentIntent, currentIntentRecord, err := ledger.refreshCurrentIntent(ctx, scope, intent, intentBytes)
	if err != nil {
		return SlotState{}, err
	}
	if !sameIntent(currentIntent, intent) || currentIntentRecord.SHA256 != intentRecord.SHA256 {
		return SlotState{}, ErrRecordAuthorization
	}
	intentRecord = currentIntentRecord
	if err := ledger.validateCurrentAuthority(ctx); err != nil {
		return SlotState{}, err
	}
	_, headRecord, err := ledger.writeInitialHead(ctx, scope, head, initialHeadBytes, headAuthorizedNow)
	if err != nil {
		return SlotState{}, err
	}
	if err := validateStoredBeforeExpiry(headRecord, intentEnvelope.ExpiresAt); err != nil {
		return SlotState{}, err
	}
	if err := validateHeadWithinRetryWindow(headRecord, intentRecord); err != nil {
		return SlotState{}, err
	}
	if err := ledger.validateStoredBeforeAnchorExpiry(headRecord); err != nil {
		return SlotState{}, err
	}
	return ledger.ReadSlot(ctx, scope)
}

// ReadSlot returns a historically verified record view. It does not authorize
// a cloud mutation; use ReadForLaunch for a current signed, unexpired intent.
func (ledger *Ledger) ReadSlot(ctx context.Context, scope BootstrapScope) (SlotState, error) {
	state, err := ledger.readSlot(ctx, scope, false)
	if err == nil {
		return state, nil
	}
	// Managed peer records can be valid historical evidence whose
	// signed interval or exact proof timing is no longer current. Preserve that
	// distinction for read-only callers while keeping malformed or mismatched
	// records as hard errors.
	quarantined, recoveryErr := ledger.readSlotWithRecovery(ctx, scope, false, true)
	if recoveryErr == nil && quarantined.Intent.Mode == IntentModeManaged &&
		quarantined.quarantined {
		return SlotState{}, fmt.Errorf("%w: slot %q", ErrManagedPeerProofQuarantined, scope.Slot)
	}
	return SlotState{}, err
}

func (ledger *Ledger) RecordManagedPeer(
	ctx context.Context,
	scope BootstrapScope,
	manifestBytes []byte,
	peerReceiptBytes []byte,
	facts InstanceFacts,
	resultBytes []byte,
	headWithResultBytes []byte,
	signProgress ManagedPeerProgressSigner,
	refresh ManagedPeerRecoveryRefresh,
) (SlotState, error) {
	manifestBytes = bytes.Clone(manifestBytes)
	peerReceiptBytes = bytes.Clone(peerReceiptBytes)
	resultBytes = bytes.Clone(resultBytes)
	headWithResultBytes = bytes.Clone(headWithResultBytes)
	facts.Profile = cloneProfile(facts.Profile)
	state, err := ledger.readSlotForManagedPeerRecovery(ctx, scope)
	if err != nil {
		return SlotState{}, err
	}
	var lastRecoveryReadID uint64
	refreshCurrent := func() (VerifiedFounderPeer, error) {
		peer, refreshErr := ledger.refreshManagedPeer(ctx, scope, state, refresh)
		if refreshErr != nil {
			return VerifiedFounderPeer{}, refreshErr
		}
		if peer.recovery.readID == 0 || peer.recovery.readID <= lastRecoveryReadID {
			return VerifiedFounderPeer{}, fmt.Errorf("%w: managed-peer transition reused a recovery authorization", ErrRecordAuthorization)
		}
		lastRecoveryReadID = peer.recovery.readID
		return peer, nil
	}
	if state.Intent.Mode != IntentModeManaged {
		return SlotState{}, ErrExternalSeedMode
	}
	if state.Candidate == nil || state.CandidateRecord == nil ||
		state.Candidate.InstanceOCID != facts.InstanceOCID ||
		validateManagedPeerCandidateForIntent(*state.Candidate, state.Intent, state.IntentRecord.SHA256,
			state.Intent.FounderPlanSHA256, state.Intent.PeerRowDigest, state.Intent.ManifestDigest) != nil {
		return SlotState{}, fmt.Errorf("%w: managed-peer completion requires the exact pinned candidate", ErrRecordAuthorization)
	}
	result, err := ledger.decodeResult(scope, resultBytes, false)
	if err != nil {
		return SlotState{}, err
	}
	if result.Mode != IntentModeManaged || result.PeerReceiptDigest != objectDigest(peerReceiptBytes) || result.SeedReceiptDigest != "" {
		return SlotState{}, ErrSlotHeadConflict
	}
	if state.Head.ResultDigest != "" && !state.quarantined {
		if state.Head.ResultDigest == objectDigest(resultBytes) && state.ResultRecord != nil &&
			bytes.Equal(state.ResultRecord.Bytes, resultBytes) && state.ManifestRecord != nil &&
			state.ManifestRecord.SHA256 == objectDigest(manifestBytes) && bytes.Equal(state.ManifestRecord.Bytes, manifestBytes) &&
			state.PeerReceiptRecord != nil && state.PeerReceiptRecord.SHA256 == objectDigest(peerReceiptBytes) &&
			bytes.Equal(state.PeerReceiptRecord.Bytes, peerReceiptBytes) {
			return cloneSlotState(state), nil
		}
		return SlotState{}, ErrSlotHeadConflict
	} else if state.Head.ResultDigest != "" && state.Head.ResultDigest == objectDigest(resultBytes) &&
		state.ResultRecord != nil && bytes.Equal(state.ResultRecord.Bytes, resultBytes) &&
		state.ManifestRecord != nil && bytes.Equal(state.ManifestRecord.Bytes, manifestBytes) &&
		state.PeerReceiptRecord != nil && bytes.Equal(state.PeerReceiptRecord.Bytes, peerReceiptBytes) {
		// A quarantined completed HEAD can be repaired only with fresh signed
		// proof bytes. Replaying the same late completion would preserve the
		// quarantine and must not perform another write.
		return SlotState{}, ErrManagedPeerProofQuarantined
	}
	if state.Head.Attempt != result.Attempt || state.Head.Generation != result.Generation ||
		state.Head.IntentDigest != result.IntentDigest || result.IntentDigest != state.IntentRecord.SHA256 {
		return SlotState{}, ErrSlotHeadConflict
	}
	if err := validateResultForIntent(result, state.Intent, state.IntentRecord.SHA256); err != nil {
		return SlotState{}, err
	}
	if err := validateManagedFacts(ledger, facts, state.Intent, state.IntentRecord.SHA256, result); err != nil {
		return SlotState{}, err
	}
	manifestRecord, manifestExists, err := ledger.readExistingExact(ctx, scope, state.Head.Attempt, ledgerManifest, manifestBytes)
	if err != nil {
		return SlotState{}, err
	}
	receiptRecord, receiptExists, err := ledger.readContentExact(ctx, scope, state.Head.Attempt, ledgerPeerReceipt, peerReceiptBytes)
	if err != nil {
		return SlotState{}, err
	}
	resultRecord, resultExists, err := ledger.readContentExact(ctx, scope, result.Attempt, ledgerResult, resultBytes)
	if err != nil {
		return SlotState{}, err
	}
	if resultExists && (!manifestExists || !receiptExists) {
		return SlotState{}, fmt.Errorf("%w: an existing result cannot authorize creating a missing manifest or peer receipt", ErrRecordAuthorization)
	}
	if result.PeerReceiptDigest != objectDigest(peerReceiptBytes) || objectDigest(manifestBytes) != state.Intent.ManifestDigest {
		return SlotState{}, ErrSlotHeadConflict
	}

func (ledger *Ledger) RecordManagedPeerCandidate(ctx context.Context, scope BootstrapScope,
	candidateWire []byte, signProgress ManagedPeerProgressSigner, refresh ManagedPeerRecoveryRefresh,
) error {
	if err := ledger.validateAnchorScope(scope); err != nil {
		return err
	}
	baseline, err := ledger.readSlotForManagedPeerRecovery(ctx, scope)
	if err != nil {
		return err
	}
	if baseline.Intent.Mode != IntentModeManaged || baseline.Intent.SchemaVersion != 1 || baseline.Head.SchemaVersion != 1 {
		return ErrFounderPlanRequired
	}
	candidate, candidateEnvelope, err := ledger.decodeManagedPeerCandidate(scope, candidateWire, true)
	if err != nil {
		return err
	}
	if err := validateManagedPeerCandidateForIntent(candidate, baseline.Intent, baseline.IntentRecord.SHA256,
		baseline.Intent.FounderPlanSHA256, baseline.Intent.PeerRowDigest, baseline.Intent.ManifestDigest); err != nil {
		return err
	}
	if err := ledger.validateCurrentAuthority(ctx); err != nil {
		return err
	}
	peer, err := ledger.refreshManagedPeer(ctx, scope, baseline, refresh)
	if err != nil {
		return err
	}
	if peer.recovery.phase != ManagedPeerRecoveryClean && peer.recovery.phase != ManagedPeerRecoveryManifestOnly &&
		peer.recovery.phase != ManagedPeerRecoveryCandidateOnly {
		return ErrRecordAuthorization
	}
	if peer.recovery.phase == ManagedPeerRecoveryCandidateOnly {
		stored := peer.recovery.state.CandidateRecord
		if stored == nil || !bytes.Equal(stored.Bytes, candidateWire) {
			return ErrImmutableConflict
		}
		if progressRecord := peer.recovery.state.ProgressRecord; progressRecord != nil {
			return nil
		}
	}
	if !peer.recovery.AuthorizationTime().Before(candidateEnvelope.ExpiresAt) {
		return fmt.Errorf("%w: candidate signature is not current at the refreshed recovery clock", ErrRecordAuthorization)
	}
	candidateRecord, err := ledger.createOrRead(ctx, scope, baseline.Head.Attempt, ledgerCandidate, candidateWire)
	if err != nil {
		return err
	}
	if err := validateStoredInterval(candidateRecord, candidateEnvelope); err != nil {
		return err
	}
	if err := ledger.validateStoredBeforeAnchorExpiry(candidateRecord); err != nil {
		return err
	}
	baseline.Candidate = &candidate
	baseline.CandidateRecord = &candidateRecord
	_, progress, err := ledger.readManagedPeerProgress(ctx, scope, baseline.Head.Attempt, false)
	if err == nil {
		if progress.CandidateDigest != candidateRecord.SHA256 {
			return ErrImmutableConflict
		}
		return nil
	}
	if !errors.Is(err, ErrRecordMissing) {
		return err
	}
	peer, err = ledger.refreshManagedPeer(ctx, scope, baseline, refresh)
	if err != nil {
		return err
	}
	if peer.recovery.phase != ManagedPeerRecoveryCandidateOnly || peer.recovery.state.CandidateRecord == nil ||
		peer.recovery.state.CandidateRecord.SHA256 != candidateRecord.SHA256 {
		return ErrRecordAuthorization
	}
	progress = ManagedPeerProgress{
		SchemaVersion: 1, DeploymentID: scope.DeploymentID, Cell: scope.Cell,
		Environment: ledger.config.Environment, Role: roleController, Slot: scope.Slot,
		Attempt: baseline.Head.Attempt, Generation: baseline.Head.Generation, Sequence: 1,
		CandidateDigest: candidateRecord.SHA256, Phase: ManagedPeerProgressCandidate,
	}
	progressWire, progressEnvelope, err := ledger.signManagedPeerProgress(peer, progress, signProgress)
	if err != nil {
		return err
	}
	peer, err = ledger.refreshManagedPeer(ctx, scope, baseline, refresh)
	if err != nil {
		return err
	}
	if err := ensureCandidateAndProgressBaseline(peer, candidateRecord.SHA256, 0, ""); err != nil {
		return err
	}
	effectCtx, cancel, err := managedPeerEffectContext(ctx, peer, time.Time{}, progressEnvelope.ExpiresAt)
	if err != nil {
		return err
	}
	defer cancel()
	_, _, err = ledger.writeManagedPeerProgress(effectCtx, scope, baseline.Head.Attempt, "", progress, progressWire, progressEnvelope)
	return err
}

